      ja: "ゆっくりはっきり話せば伝わります。速くて曖昧では伝わりません。",
      "zh-CN": "慢而清楚，别人听得懂；快而含糊，就听不懂。",
      es: "Lento y claro se entiende. Rápido y borroso, no.",
      fr: "Lent et clair, on vous comprend. Rapide et flou, non.",
      de: "Langsam und deutlich versteht man. Schnell und verwaschen nicht.",
      "pt-BR": "Devagar e claro se entende. Rápido e embolado, não.",
      vi: "Chậm và rõ thì người ta hiểu. Nhanh và nhòe thì không.",
      th: "ช้าและชัด คนเข้าใจ เร็วและเบลอ คนไม่เข้าใจ",
      ar: "البطيء الواضح يُفهم، والسريع المبهم لا.",
      bn: "ধীরে ও স্পষ্ট বললে বোঝা যায়; দ্রুত ও ঝাপসা হলে যায় না।",
      cs: "Pomalu a zřetelně vám rozumí. Rychle a rozmazaně ne.",
      el: "Αργά και καθαρά σε καταλαβαίνουν. Γρήγορα και θολά όχι.",
      fil: "Ang mabagal at malinaw ay naiintindihan. Ang mabilis at malabo ay hindi.",
      hi: "धीरे और साफ़ बोलें तो समझ आता है; तेज़ और धुँधला नहीं।",
      hu: "Lassan és tisztán megértik. Gyorsan és elmosódottan nem.",
      id: "Pelan dan jelas akan dimengerti. Cepat dan kabur tidak.",
      it: "Lento e chiaro si capisce. Veloce e impastato no.",
      kk: "Баяу әрі анық сөйлесеңіз түсінеді. Жылдам әрі күңгірт болса түсінбейді.",
